#!/bin/bash
# Build the kRPC for KSA documentation into experimental/ksa/bin/docs, as HTML.
#
#   docs.sh          build the HTML
#   docs.sh --serve  also serve it on http://127.0.0.1:8000, or PORT
#
# The API pages are generated by krpc-docgen from bin/KRPC.KSA.json, so run build.sh
# first. Sphinx and its extensions are installed into a virtualenv.
set -euo pipefail


here="$(dirname "$(readlink -f "$0")")"
source "$here/versions.sh"
repo="$(dirname "$(dirname "$here")")"
src="$here/bin/doc-src"
out="$here/bin/docs"

serve=0
for arg in "$@"; do
  case "$arg" in
    --serve) serve=1 ;;
    *) echo "unknown argument: $arg" >&2; exit 1 ;;
  esac
done

if [ ! -f "$here/bin/KRPC.KSA.json" ]; then
  echo "bin/KRPC.KSA.json not found, run build.sh first" >&2
  exit 1
fi

venv="$here/bin/doc-venv"
if ! cmp -s "$here/doc/requirements.txt" "$venv/requirements.txt"; then
  rm -rf "$venv"
  python3 -m venv "$venv"
  "$venv/bin/pip" install --quiet --disable-pip-version-check -r "$here/doc/requirements.txt"
  cp "$here/doc/requirements.txt" "$venv/requirements.txt"
fi

rm -rf "$src" "$out"
cp -r "$here/doc" "$src"
rm "$src/requirements.txt"
mkdir -p "$src/scripts"
cp "$here"/examples/*.py "$src/scripts/"
# One API page per template, under each language's api folder
for language in python csharp cpp cnano java lua; do
  (cd "$here/doc/api" && find . -name '*.tmpl') | while read -r template; do
    page="$src/$language/api/${template%.tmpl}.rst"
    mkdir -p "$(dirname "$page")"
    "$here/bin/venv/bin/krpc-docgen" "$language" "$here/doc/api/$template" "$here/doc/order.txt" \
      "$page" "$here/bin/KRPC.KSA.json"
  done
done

# The changelog page, generated as for the kRPC documentation
python3 "$repo/doc/changeloggen.py" "$src/changelog.rst" --entry "kRPC for KSA" "$here/CHANGELOG.md"

find "$src" -name '*.rst' -exec sed -i \
  -e "s/@VERSION@/$mod_version/g" -e "s/@KRPC_VERSION@/$krpc_version/g" \
  -e "s/@STARMAP_VERSION@/$starmap_version/g" -e "s/@KSA_VERSION@/$ksa_version/g" {} +
PYTHONWARNINGS="ignore:pkg_resources is deprecated:UserWarning" KSA_DOC_VERSION="$mod_version" "$venv/bin/sphinx-build" -q -W -b html "$src" "$out"
echo "Documentation in $out/index.html"

if [ "$serve" = 1 ]; then
  exec python3 -m http.server --bind 127.0.0.1 --directory "$out" "${PORT:-8000}"
fi
